arguments.command:
cd /tmp/vally-eval-trial-SlDrf7 && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Gold }

public sealed record CalculatePayableTotal(CustomerTier Tier, decimal Subtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotal command) => command.Subtotal;
}
E
mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotal(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -vi warn | tail -25

